<script setup lang="ts">definePageMeta({layout:"default"});useSeoMeta({title:"صف پالایش محتوا | هفت‌سو",robots:"noindex,nofollow"});const{cases,decide,load,message,metrics,pending,selected}=useModeration(),state=ref("open");onMounted(()=>load());watch(state,(value:string)=>load(value));</script>
<template><main id="main-content" class="moderation-admin content-container"><header class="moderation-admin-header"><div><p class="eyebrow">مرکز اعتماد هفت‌سو</p><h1>پالایش هوشمند محتوا</h1><p>هوش مصنوعی شواهد را مرتب می‌کند؛ تصمیم پاسخ‌گو و قابل اعتراض با انسان است.</p></div><label>وضعیت صف<select v-model="state"><option value="open">در انتظار بررسی</option><option value="appealed">اعتراض‌ها</option><option value="resolved">بسته‌شده</option><option value="all">همه</option></select></label></header><section class="moderation-metrics" aria-label="شاخص‌های پالایش"><article><strong>{{metrics.backlog}}</strong><span>پرونده باز</span></article><article><strong>{{metrics.resolved}}</strong><span>حل‌شده در ۳۰ روز</span></article><article><strong>{{metrics.avg_minutes}}</strong><span>میانگین دقیقه بررسی</span></article><article><strong>{{metrics.duplicate_cases}}</strong><span>موارد تکراری</span></article></section><UiState v-if="pending" kind="loading" title="در حال دریافت صف" description="پرونده‌ها بر پایه اولویت مرتب می‌شوند."/><UiState v-else-if="!cases.length" kind="empty" title="صف بررسی خالی است" description="در حال حاضر پرونده‌ای برای این وضعیت وجود ندارد."/><div v-else class="moderation-workspace"><ModerationQueue :items="cases" :active-id="selected?.id" @select="selected=$event"/><div v-if="selected" class="moderation-review"><ModerationCasePanel :item="selected"/><ModerationDecisionForm :case-id="selected.id" @decide="decide"/></div></div><p v-if="message" class="post-action-message" role="status">{{message}}</p></main></template>
